package org.apache.commons.io.monitor;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.attribute.FileTime;
import java.util.Objects;

import org.apache.commons.io.FileUtils;
import org.apache.commons.io.file.attribute.FileTimes;
import org.apache.commons.io.file.attribute.SerializableFileTime;

public class FileEntryAttributes {

    private String name;
    private boolean exists;
    private boolean directory;
    private SerializableFileTime lastModified;
    private long length;

    public FileEntryAttributes() {
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public boolean isExists() {
        return exists;
    }

    public void setExists(boolean exists) {
        this.exists = exists;
    }

    public boolean isDirectory() {
        return directory;
    }

    public void setDirectory(boolean directory) {
        this.directory = directory;
    }

    public SerializableFileTime getLastModified() {
        return lastModified;
    }

    public FileTime getLastModifiedFileTime() {
        return lastModified;
    }

    public void setLastModified(FileTime fileTime) {
        this.lastModified = (fileTime == null) ? null : new SerializableFileTime(fileTime);
    }

    public void setLastModified(long time) {
        setLastModified(FileTime.fromMillis(time));
    }

    /* package-private as requested in the plan */
    void setLastModified(SerializableFileTime fileTime) {
        this.lastModified = fileTime;
    }

    public long getLength() {
        return length;
    }

    public void setLength(long length) {
        this.length = length;
    }

    /**
     * Refresh the attributes from the given File. Returns true if any attribute changed.
     */
    public boolean refresh(File file) {
        boolean changed = false;

        String newName = file.getName();
        boolean newExists = Files.exists(file.toPath());
        boolean newDirectory = file.isDirectory();
        long newLength = file.length();

        FileTime newFileTime = null;
        try {
            newFileTime = FileUtils.lastModifiedFileTime(file);
        } catch (IOException e) {
            // Mirror original behavior: if we cannot read last modified time, treat as null
            newFileTime = null;
        }

        SerializableFileTime newLastModified = (newFileTime == null) ? null : new SerializableFileTime(newFileTime);

        if (!Objects.equals(this.name, newName)) {
            this.name = newName;
            changed = true;
        }
        if (this.exists != newExists) {
            this.exists = newExists;
            changed = true;
        }
        if (this.directory != newDirectory) {
            this.directory = newDirectory;
            changed = true;
        }
        if (!Objects.equals(this.lastModified, newLastModified)) {
            this.lastModified = newLastModified;
            changed = true;
        }
        if (this.length != newLength) {
            this.length = newLength;
            changed = true;
        }

        return changed;
    }
}
